versions.variantCss:
.wemd-cta-card[data-variant="bytedance-cta-bold"] {
  background: linear-gradient(135deg, var(--wemd-primary), var(--wemd-primary-dark));
  border-radius: var(--wemd-border-radius);
  padding: 32px 28px;
  margin: 24px 0;
  text-align: center;
  box-shadow: var(--wemd-shadow);
}
.wemd-cta-card[data-variant="bytedance-cta-bold"] .wemd-component-body {
  padding: 0;
}
.wemd-cta-card[data-variant="bytedance-cta-bold"] .wemd-component-body .wemd-child-1 {
  color: #ffffff;
  font-size: 22px;
  font-weight: 700;
  margin: 0 0 8px 0;
}
.wemd-cta-card[data-variant="bytedance-cta-bold"] .wemd-component-body .wemd-child-2 {
  color: rgba(255, 255, 255, 0.9);
  font-size: 14px;
  margin: 0 0 20px 0;
}
.wemd-cta-card[data-variant="bytedance-cta-bold"] .wemd-component-body .wemd-child-3 {
  display: inline-block;
  background: #ffffff;
  color: var(--wemd-primary);
  font-size: 15px;
  font-weight: 700;
  padding: 10px 32px;
  border-radius: 999px;
  margin: 0;
}
